import React, { useState, useEffect } from 'react';
import {
    Card,
    Form,
    Input,
    Select,
    Button,
    Space,
    Typography,
    message,
    Breadcrumb,
    Alert,
    Modal,
    theme
} from 'antd';
import {
    UserAddOutlined,
    ArrowLeftOutlined,
    CheckCircleOutlined,
    HomeOutlined,
    TeamOutlined
} from '@ant-design/icons';
import { getCsrfToken } from '../../utils/csrf';
import { callFrappePostMethod } from '../../services/api';

const { Title, Text } = Typography;

interface CreateUserPageProps {
    navigateToRoute: (route: string, id?: string) => void;
}

interface Department {
    name: string;
}

const CreateUserPage: React.FC<CreateUserPageProps> = ({ navigateToRoute }) => {
    const { token } = theme.useToken();
    const [form] = Form.useForm();
    const [submitting, setSubmitting] = useState(false);
    const [departments, setDepartments] = useState<Department[]>([]);
    const [tempPassword, setTempPassword] = useState<string | null>(null);
    const [showSuccessModal, setShowSuccessModal] = useState(false);
    const [createdUserEmail, setCreatedUserEmail] = useState<string>('');

    // Fetch departments
    useEffect(() => {
        const fetchDepartments = async () => {
            try {
                const response = await fetch('/api/method/frappe.client.get_list', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'X-Frappe-CSRF-Token': getCsrfToken()
                    },
                    credentials: 'include',
                    body: JSON.stringify({
                        doctype: 'Department',
                        fields: ['name'],
                        limit_page_length: 1000
                    })
                });

                if (response.ok) {
                    const result = await response.json();
                    setDepartments(result.data);
                }
            } catch (error) {
                console.error('Error fetching departments:', error);
            }
        };

        fetchDepartments();
    }, []);

    // Handle form submission
    const handleSubmit = async (values: any) => {
        setSubmitting(true);

        try {
            const result = await callFrappePostMethod<{ temp_password: string; user: { email: string } }>('careverse_hq.api.user_management.create_team_user', {
                first_name: values.first_name,
                last_name: values.last_name,
                email: values.email,
                phone: values.phone,
                role: values.role,
                county: values.county,
            });

            if (!result.success) {
                throw new Error(result.error || 'Failed to create user');
            }

            setTempPassword(result.data?.temp_password ?? null);
            setCreatedUserEmail(result.data?.user?.email ?? values.email);
            setShowSuccessModal(true);
            message.success('User created successfully!');
            form.resetFields();

        } catch (error: any) {
            console.error('Error creating user:', error);
            message.error(error.message || 'Failed to create user');
        } finally {
            setSubmitting(false);
        }
    };

    // Copy password to clipboard
    const copyPassword = () => {
        if (tempPassword) {
            navigator.clipboard.writeText(tempPassword);
            message.success('Password copied to clipboard');
        }
    };

    // Handle modal close
    const handleModalClose = () => {
        setShowSuccessModal(false);
        navigateToRoute('user-management');
    };

    return (
        <div style={{ padding: '20px', maxWidth: 760, margin: '0 auto' }}>
            {/* Breadcrumb */}
            <Breadcrumb style={{ marginBottom: 16 }}>
                <Breadcrumb.Item>
                    <HomeOutlined />
                </Breadcrumb.Item>
                <Breadcrumb.Item>
                    <a onClick={() => navigateToRoute('user-management')}>
                        <TeamOutlined /> User Management
                    </a>
                </Breadcrumb.Item>
                <Breadcrumb.Item>Create User</Breadcrumb.Item>
            </Breadcrumb>

            {/* Main Card */}
            <Card
                style={{
                    borderRadius: 12,
                    border: 'none',
                    boxShadow: '0 2px 12px rgba(0,0,0,0.08)'
                }}
            >
                {/* Header */}
                <div style={{ marginBottom: 20 }}>
                    <Title level={3} style={{ margin: 0, marginBottom: 4 }}>
                        <UserAddOutlined style={{ marginRight: 10, color: token.colorPrimary }} />
                        Create New User
                    </Title>
                    <Text type="secondary">
                        Create a new team member with access to the system
                    </Text>
                </div>

                {/* Info Alert */}
                <Alert
                    message="User Credentials"
                    description="A temporary password will be automatically generated and sent to the user via email. The user will be required to change their password upon first login."
                    type="info"
                    showIcon
                    style={{ marginBottom: 24, borderRadius: 8 }}
                />

                {/* Form */}
                <Form
                    form={form}
                    layout="vertical"
                    onFinish={handleSubmit}
                    requiredMark="optional"
                >
                    <Form.Item
                        label="First Name"
                        name="first_name"
                        rules={[{ required: true, message: 'Please enter first name' }]}
                    >
                        <Input placeholder="Enter first name" />
                    </Form.Item>

                    <Form.Item
                        label="Last Name"
                        name="last_name"
                        rules={[{ required: true, message: 'Please enter last name' }]}
                    >
                        <Input placeholder="Enter last name" />
                    </Form.Item>

                    <Form.Item
                        label="Email"
                        name="email"
                        rules={[
                            { required: true, message: 'Please enter email' },
                            { type: 'email', message: 'Please enter a valid email' }
                        ]}
                    >
                        <Input placeholder="user@example.com" />
                    </Form.Item>

                    <Form.Item
                        label="Phone Number"
                        name="phone"
                    >
                        <Input placeholder="+254712345678" />
                    </Form.Item>

                    <Form.Item
                        label="Role"
                        name="role"
                        rules={[{ required: true, message: 'Please select a role' }]}
                    >
                        <Select
                            placeholder="Select user role"
                            options={[
                                { label: 'County Executive', value: 'County Executive' },
                                { label: 'Assistant', value: 'Assistant' },
                                { label: 'System Manager', value: 'System Manager' }
                            ]}
                        />
                    </Form.Item>

                    <Form.Item
                        label="County/Department"
                        name="county"
                        rules={[{ required: true, message: 'Please select a county/department' }]}
                    >
                        <Select
                            placeholder="Select county or department"
                            showSearch
                            filterOption={(input, option) =>
                                (option?.label ?? '').toLowerCase().includes(input.toLowerCase())
                            }
                            options={departments.map(dept => ({
                                label: dept.name,
                                value: dept.name
                            }))}
                        />
                    </Form.Item>

                    {/* Actions */}
                    <Form.Item style={{ marginTop: 20, marginBottom: 0 }}>
                        <Space size="middle">
                            <Button
                                icon={<ArrowLeftOutlined />}
                                onClick={() => navigateToRoute('user-management')}
                                disabled={submitting}
                            >
                                Cancel
                            </Button>
                            <Button
                                type="primary"
                                htmlType="submit"
                                icon={<CheckCircleOutlined />}
                                loading={submitting}
                            >
                                Create User
                            </Button>
                        </Space>
                    </Form.Item>
                </Form>
            </Card>

            {/* Success Modal */}
            <Modal
                title={
                    <Space>
                        <CheckCircleOutlined style={{ color: token.colorSuccess, fontSize: 20 }} />
                        <span>User Created Successfully</span>
                    </Space>
                }
                open={showSuccessModal}
                onOk={handleModalClose}
                onCancel={handleModalClose}
                footer={[
                    <Button key="copy" onClick={copyPassword}>
                        Copy Password
                    </Button>,
                    <Button key="close" type="primary" onClick={handleModalClose}>
                        Back to User List
                    </Button>
                ]}
                width={600}
            >
                <Space direction="vertical" size="large" style={{ width: '100%' }}>
                    <Alert
                        message="Email Sent"
                        description={`An email with login credentials has been sent to ${createdUserEmail}`}
                        type="success"
                        showIcon
                    />

                    <div>
                        <Text strong style={{ display: 'block', marginBottom: 8 }}>
                            Temporary Password:
                        </Text>
                        <Card style={{ background: token.colorBgContainer }}>
                            <Text
                                strong
                                style={{
                                    fontSize: 15,
                                    fontFamily: 'monospace',
                                    wordBreak: 'break-all'
                                }}
                            >
                                {tempPassword}
                            </Text>
                        </Card>
                    </div>

                    <Alert
                        message="Important"
                        description="Please securely share this password with the user. They will be required to change it upon first login."
                        type="warning"
                        showIcon
                    />
                </Space>
            </Modal>
        </div>
    );
};

export default CreateUserPage;
